<?php require_once 'functions.php'; need_login();$id=(int)($_GET['id']??0);$q=$pdo->prepare('SELECT * FROM diagnoses WHERE id=? AND user_id=?');$q->execute([$id,user()['id']]);$d=$q->fetch();if(!$d){http_response_code(404);exit('Riwayat tidak ditemukan.');}$results=json_decode($d['results_json'],true)?:[];$answers=json_decode($d['answers_json'],true)?:[];$general=json_decode($d['general_json'],true)?:[];header_html('Hasil diagnosis');?><section class="page-head no-print"><a href="<?=e(app_url('history.php'))?>">&larr; Kembali ke riwayat</a></section><section class="result card"><div class="result-top"><div><span class="eyebrow">HASIL DIAGNOSIS &middot; <?=date('d M Y H:i',strtotime($d['created_at']))?></span><h1><?=e($d['disease_name'])?></h1><p>Diagnosis kemungkinan berdasarkan gejala yang Anda pilih.</p></div><div class="score"><?=number_format($d['confidence'],1)?><small>% keyakinan</small></div></div><section class="confidence-chart" aria-labelledby="chart-title"><h2 id="chart-title">Grafik tingkat keyakinan</h2><p class="muted">Perbandingan visual skor untuk setiap kemungkinan penyakit.</p><?php if($results):?><div class="bar-chart" role="img" aria-label="Grafik batang vertikal skor keyakinan penyakit dari nol sampai seratus persen"><div class="chart-axis"><span>100%</span><span>75%</span><span>50%</span><span>25%</span><span>0%</span></div><div class="chart-plot"><?php foreach($results as $r):$chartValue=max(0,min(100,(float)$r['confidence']));?><div class="chart-column"><div class="chart-column-value" data-value="<?=$chartValue?>"><?=number_format($chartValue,1)?>%</div><div class="chart-column-track"><span class="chart-column-bar" data-height="<?=$chartValue?>" style="height:<?=$chartValue?>%"></span></div><div class="chart-column-name"><?=e($r['name'])?></div></div><?php endforeach;?></div></div><?php else:?><p class="muted">Data grafik tidak tersedia.</p><?php endif;?></section><h3>Gejala umum yang dipilih</h3><ul class="answer-list"><?php foreach($general as $g):?><li><?=e($g)?></li><?php endforeach;?></ul><h3>Jawaban gejala lanjutan</h3><ul class="answer-list"><?php foreach($answers as $a):?><li><?=e($a['name'])?> &mdash; <?=e($a['label'])?></li><?php endforeach;?></ul><div class="callout result-advice"><div><b>Catatan</b><p>Hasil ini merupakan indikasi awal berbasis aturan, bukan diagnosis laboratorium. Untuk hasil rendah atau gejala berat, dokumentasikan tanaman dan konsultasikan dengan penyuluh atau ahli perlindungan tanaman.</p></div></div><div class="form-actions no-print"><button class="button" onclick="window.print()">Cetak hasil</button><a class="button button-outline" href="<?=e(app_url('diagnosis.php'))?>">Diagnosis baru</a></div></section><?php footer_html();?>
